import { Monitor, Moon, Sun } from "lucide-react"
import { useEffect, useState } from "react"

import { PlatformIcon } from "@/components/platform-icon"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import { getThemeMode, getThemePreference, applyThemeMode, setThemePreference, subscribeThemeMode, subscribeThemePreference, type ThemeMode, type ThemePreference } from "@/lib/theme"
import { cn } from "@/lib/utils"

type ThemeSwitcherViewProps = {
  className?: string
  preference: ThemePreference
  effectiveMode: ThemeMode
  onPreferenceChange: (preference: ThemePreference) => void
}

export function ThemeSwitcherView({ className, effectiveMode, onPreferenceChange, preference }: ThemeSwitcherViewProps) {
  return (
    <ToggleGroup
      aria-label="Color mode"
      className={cn("w-fit rounded-3xl", className)}
      onValueChange={(values) => {
        const next = values[0]
        if (next === "light" || next === "dark" || next === "system") onPreferenceChange(next)
      }}
      size="sm"
      selectionVariant="container"
      spacing={1}
      value={[preference]}
    >
      <ToggleGroupItem aria-label="Use light mode" value="light">
        <PlatformIcon data-icon="inline-start" icon={Sun} />
        Light
      </ToggleGroupItem>
      <ToggleGroupItem aria-label="Use dark mode" value="dark">
        <PlatformIcon data-icon="inline-start" icon={Moon} />
        Dark
      </ToggleGroupItem>
      <ToggleGroupItem aria-label={`Use system mode, currently ${effectiveMode}`} value="system">
        <PlatformIcon data-icon="inline-start" icon={Monitor} />
        System
      </ToggleGroupItem>
    </ToggleGroup>
  )
}

export function ThemeSwitcher({ className }: { className?: string }) {
  const [preference, setPreference] = useState<ThemePreference>(() => getThemePreference())
  const [effectiveMode, setEffectiveMode] = useState<ThemeMode>(() => getThemeMode())

  useEffect(() => {
    applyThemeMode(effectiveMode)
    return subscribeThemeMode(setEffectiveMode)
  }, [effectiveMode])

  useEffect(() => subscribeThemePreference(setPreference), [])

  return (
    <ThemeSwitcherView
      className={className}
      effectiveMode={effectiveMode}
      preference={preference}
      onPreferenceChange={(nextPreference) => {
        setPreference(nextPreference)
        setThemePreference(nextPreference)
        setEffectiveMode(nextPreference === "system" ? getThemeMode() : nextPreference)
      }}
    />
  )
}

import type { LucideIcon, LucideProps } from "lucide-react"

import { cn } from "@/lib/utils"

const iconSizes = {
  xs: "size-3",
  sm: "size-3.5",
  md: "size-4",
  lg: "size-5",
} as const

type PlatformIconProps = Omit<LucideProps, "size"> & {
  icon: LucideIcon
  size?: keyof typeof iconSizes
}

/**
 * The canonical visual grid for platform UI glyphs.
 *
 * App artwork uses AppIdentity instead: it is deliberately larger and never
 * substitutes for navigation, action, status, or inline-content glyphs.
 */
export function PlatformIcon({ className, icon: Icon, size = "md", ...props }: PlatformIconProps) {
  const label = props["aria-label"]
  return <Icon aria-hidden={label ? undefined : true} data-slot="platform-icon" focusable="false" {...props} className={cn("shrink-0", iconSizes[size], className)} />
}

"use client"

import * as React from "react"
import { Toggle as TogglePrimitive } from "@base-ui/react/toggle"
import { ToggleGroup as ToggleGroupPrimitive } from "@base-ui/react/toggle-group"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"
import { toggleVariants } from "@/components/ui/toggle"

const toggleGroupSelectionVariants = cva("", {
  variants: {
    selectionVariant: {
      default: "",
      container: "border border-border bg-container p-1",
    },
  },
  defaultVariants: {
    selectionVariant: "default",
  },
})

const toggleGroupItemSelectionVariants = cva("", {
  variants: {
    selectionVariant: {
      default: "",
      container: "aria-pressed:bg-container",
    },
  },
  defaultVariants: {
    selectionVariant: "default",
  },
})

const ToggleGroupContext = React.createContext<
  VariantProps<typeof toggleVariants> & {
    selectionVariant?: "default" | "container"
    spacing?: number
    orientation?: "horizontal" | "vertical"
  }
>({
  size: "default",
  variant: "default",
  spacing: 2,
  orientation: "horizontal",
})

function ToggleGroup({
  className,
  variant,
  size,
  selectionVariant = "default",
  spacing = 2,
  orientation = "horizontal",
  children,
  ...props
}: ToggleGroupPrimitive.Props &
  VariantProps<typeof toggleVariants> & {
    selectionVariant?: "default" | "container"
    spacing?: number
    orientation?: "horizontal" | "vertical"
  }) {
  const contextValue = React.useMemo(
    () => ({ variant, size, selectionVariant, spacing, orientation }),
    [orientation, selectionVariant, size, spacing, variant]
  )

  return (
    <ToggleGroupPrimitive
      data-slot="toggle-group"
      data-variant={variant}
      data-size={size}
      data-selection-variant={selectionVariant}
      data-spacing={spacing}
      data-surface={selectionVariant === "container" ? "container" : undefined}
      data-orientation={orientation}
      style={{ "--gap": spacing } as React.CSSProperties}
      className={cn(
        "group/toggle-group flex w-fit flex-row items-center gap-[--spacing(var(--gap))] data-[spacing=0]:data-[variant=outline]:rounded-3xl data-vertical:flex-col data-vertical:items-stretch",
        toggleGroupSelectionVariants({ selectionVariant }),
        className,
        selectionVariant === "container" && "bg-container"
      )}
      {...props}
    >
      <ToggleGroupContext.Provider value={contextValue}>
        {children}
      </ToggleGroupContext.Provider>
    </ToggleGroupPrimitive>
  )
}

function ToggleGroupItem({
  className,
  children,
  variant = "default",
  size = "default",
  selectionVariant = "default",
  ...props
}: TogglePrimitive.Props &
  VariantProps<typeof toggleVariants> &
  VariantProps<typeof toggleGroupItemSelectionVariants>) {
  const context = React.useContext(ToggleGroupContext)

  return (
    <TogglePrimitive
      data-slot="toggle-group-item"
      data-variant={context.variant || variant}
      data-size={context.size || size}
      data-selection-variant={context.selectionVariant || selectionVariant}
      data-spacing={context.spacing}
      className={cn(
        "shrink-0 group-data-[spacing=0]/toggle-group:rounded-none group-data-[spacing=0]/toggle-group:px-3 group-data-[spacing=0]/toggle-group:shadow-none focus:z-10 focus-visible:z-10 group-data-[spacing=0]/toggle-group:has-data-[icon=inline-end]:pr-2.5 group-data-[spacing=0]/toggle-group:has-data-[icon=inline-start]:pl-2.5 group-data-horizontal/toggle-group:data-[spacing=0]:first:rounded-l-3xl group-data-vertical/toggle-group:data-[spacing=0]:first:rounded-t-3xl group-data-horizontal/toggle-group:data-[spacing=0]:last:rounded-r-3xl group-data-vertical/toggle-group:data-[spacing=0]:last:rounded-b-3xl group-data-horizontal/toggle-group:data-[spacing=0]:data-[variant=outline]:border-l-0 group-data-vertical/toggle-group:data-[spacing=0]:data-[variant=outline]:border-t-0 group-data-horizontal/toggle-group:data-[spacing=0]:data-[variant=outline]:first:border-l group-data-vertical/toggle-group:data-[spacing=0]:data-[variant=outline]:first:border-t",
        toggleVariants({
          variant: context.variant || variant,
          size: context.size || size,
        }),
        toggleGroupItemSelectionVariants({ selectionVariant: context.selectionVariant || selectionVariant }),
        className,
        (context.selectionVariant || selectionVariant) === "container" && "aria-pressed:bg-container"
      )}
      {...props}
    >
      {children}
    </TogglePrimitive>
  )
}

export { ToggleGroup, ToggleGroupItem }

export type ThemeMode = "light" | "dark"
export type ThemePreference = ThemeMode | "system"

export const THEME_STORAGE_KEY = "theme"
export const THEME_CHANGE_EVENT = "usernode:theme-change"

const darkQuery = "(prefers-color-scheme: dark)"
const themeColors: Record<ThemeMode, string> = {
  light: "#ffffff",
  dark: "#0a0a0a",
}

function isThemeMode(value: string | null): value is ThemeMode {
  return value === "light" || value === "dark"
}

function isThemePreference(value: string | null): value is ThemePreference {
  return value === "system" || isThemeMode(value)
}

export function getStoredThemePreference(): ThemePreference | null {
  if (typeof window === "undefined") return null
  try {
    const value = window.localStorage.getItem(THEME_STORAGE_KEY)
    return isThemePreference(value) ? value : null
  } catch {
    return null
  }
}

/** Compatibility alias for consumers that only care about an explicit mode. */
export function getStoredThemeMode(): ThemeMode | null {
  const preference = getStoredThemePreference()
  return isThemeMode(preference) ? preference : null
}

export function getSystemThemeMode(): ThemeMode {
  if (typeof window === "undefined") return "light"
  return window.matchMedia(darkQuery).matches ? "dark" : "light"
}

export function getThemeMode(): ThemeMode {
  return resolveThemePreference(getThemePreference())
}

export function getThemePreference(): ThemePreference {
  return getStoredThemePreference() ?? "system"
}

export function resolveThemePreference(preference: ThemePreference): ThemeMode {
  return preference === "system" ? getSystemThemeMode() : preference
}

export function applyThemeMode(mode: ThemeMode) {
  if (typeof document === "undefined") return
  const root = document.documentElement
  root.classList.remove("light", "dark")
  root.classList.add(mode)
  root.dataset.theme = mode
  root.style.colorScheme = mode
  document.querySelector('meta[name="theme-color"]')?.setAttribute("content", themeColors[mode])
}

export function setThemeMode(mode: ThemeMode) {
  setThemePreference(mode)
}

export function setThemePreference(preference: ThemePreference) {
  const mode = resolveThemePreference(preference)
  applyThemeMode(mode)
  try {
    window.localStorage.setItem(THEME_STORAGE_KEY, preference)
  } catch {
    // The current document still changes even when persistence is unavailable.
  }
  window.dispatchEvent(new CustomEvent(THEME_CHANGE_EVENT, { detail: { mode, preference } }))
}

/**
 * Watches the stored intent as distinct from the resolved light/dark mode.
 * Older event producers that publish only `{ mode }` remain valid: their mode
 * is treated as an explicit preference for subscribers that need one.
 */
export function subscribeThemePreference(listener: (preference: ThemePreference) => void) {
  if (typeof window === "undefined") return () => undefined

  const onThemeChange = (event: Event) => {
    const detail = (event as CustomEvent<{ mode?: string; preference?: string }>).detail
    const preference = detail?.preference ?? null
    const mode = detail?.mode ?? null
    if (isThemePreference(preference)) {
      listener(preference)
      return
    }
    if (isThemeMode(mode)) {
      listener(mode)
      return
    }
    listener(getThemePreference())
  }
  const onStorage = (event: StorageEvent) => {
    if (event.key !== THEME_STORAGE_KEY) return
    listener(isThemePreference(event.newValue) ? event.newValue : "system")
  }

  window.addEventListener(THEME_CHANGE_EVENT, onThemeChange)
  window.addEventListener("storage", onStorage)

  return () => {
    window.removeEventListener(THEME_CHANGE_EVENT, onThemeChange)
    window.removeEventListener("storage", onStorage)
  }
}

export function subscribeThemeMode(listener: (mode: ThemeMode) => void) {
  if (typeof window === "undefined") return () => undefined

  const media = window.matchMedia(darkQuery)
  const onThemeChange = (event: Event) => {
    const mode = (event as CustomEvent<{ mode?: string }>).detail?.mode ?? null
    if (isThemeMode(mode)) listener(mode)
  }
  const onStorage = (event: StorageEvent) => {
    if (event.key !== THEME_STORAGE_KEY) return
    const mode = resolveThemePreference(isThemePreference(event.newValue) ? event.newValue : "system")
    applyThemeMode(mode)
    listener(mode)
  }
  const onSystemChange = () => {
    if (getThemePreference() !== "system") return
    const mode = getSystemThemeMode()
    applyThemeMode(mode)
    listener(mode)
  }

  window.addEventListener(THEME_CHANGE_EVENT, onThemeChange)
  window.addEventListener("storage", onStorage)
  media.addEventListener("change", onSystemChange)

  return () => {
    window.removeEventListener(THEME_CHANGE_EVENT, onThemeChange)
    window.removeEventListener("storage", onStorage)
    media.removeEventListener("change", onSystemChange)
  }
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
